import { Injectable, OnModuleDestroy, OnModuleInit } from "@nestjs/common";
import { PrismaPg } from "@prisma/adapter-pg";
// Generated by `npx prisma generate` into prisma/generated (see schema.prisma `output`).
import { PrismaClient } from "../../prisma/generated/client";

/**
 * The one PrismaClient for the whole API. Uses the Supabase POOLER url (port 6543).
 * Migrations and the seed use DIRECT_URL instead (prisma.config.ts / seed.ts).
 * Prisma 6: replace the constructor body with `super()`.
 */
@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit, OnModuleDestroy {
  constructor() {
    super({ adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL }) });
  }

  async onModuleInit() {
    await this.$connect();
  }

  async onModuleDestroy() {
    await this.$disconnect();
  }
}
